import React, { useState } from 'react';
import { Mail, Linkedin, Github, FileDown } from 'lucide-react';
import { hero, now, contact } from '../data/content';

// Drop a photo at public/avatar.jpg to replace the placeholder below —
// no code changes needed, this just falls back gracefully if it's missing.
function Avatar() {
  const [broken, setBroken] = useState(false);

  return (
    <div className="w-28 h-28 sm:w-32 sm:h-32 rounded-full overflow-hidden bg-indigo-50 ring-4 ring-indigo-100 flex items-center justify-center shrink-0">
      {!broken ? (
        <img
          src="/avatar.jpg"
          alt="Chetanya Makkar"
          onError={() => setBroken(true)}
          className="w-full h-full object-cover"
        />
      ) : (
        <span className="text-2xl font-semibold text-indigo-400">CM</span>
      )}
    </div>
  );
}

export default function Hero() {
  return (
    <section id="top" className="pt-28 pb-16 px-6">
      <div className="max-w-prose mx-auto flex flex-col sm:flex-row items-start gap-6">
        <Avatar />
        <div>
          <h1 className="text-3xl sm:text-4xl font-semibold tracking-tight text-zinc-900">
            {hero.eyebrow}
          </h1>
          <p className="mt-3 text-base text-zinc-600 leading-relaxed">
            {hero.title}
          </p>
          <p className="mt-2 text-zinc-500 leading-relaxed">
            {hero.subtitle}
          </p>

          <div className="mt-4 inline-flex items-center gap-2 px-4 py-2 rounded-full bg-indigo-600 text-white text-sm font-medium">
            {now.current.title}
          </div>

          <div className="mt-5 flex flex-wrap gap-2">
            <a
              href={`mailto:${contact.links.email}`}
              className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full border border-zinc-200 text-zinc-700 text-sm hover:border-indigo-300 hover:text-indigo-600 transition-colors"
            >
              <Mail size={14} /> Email
            </a>
            <a
              href={contact.links.linkedin}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full border border-zinc-200 text-zinc-700 text-sm hover:border-indigo-300 hover:text-indigo-600 transition-colors"
            >
              <Linkedin size={14} /> LinkedIn
            </a>
            <a
              href={contact.links.github}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full border border-zinc-200 text-zinc-700 text-sm hover:border-indigo-300 hover:text-indigo-600 transition-colors"
            >
              <Github size={14} /> GitHub
            </a>
            <a
              href={contact.links.resume}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-full border border-zinc-200 text-zinc-700 text-sm hover:border-indigo-300 hover:text-indigo-600 transition-colors"
            >
              <FileDown size={14} /> Resume
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}
